import React from "react";
import withNavigation from "../utils/withNavigation";
import LeftSlidebar from "./leftSlidebar";
import axiosInstance from "../configurations/instance";

class EventsList extends React.Component {
  constructor(props) {
    super(props);
    this.state = {
      events: [],
      selectedEvent: null, // Данные выбранного события
    };
  }

  componentDidMount() {
    axiosInstance
      .get("/event/all-events")
      .then((response) => {
        this.setState({ events: response.data });
      })
      .catch((error) => console.error("Ошибка при загрузке событий:", error));
  }

  handleView = (id) => {
    axiosInstance
      .get(`/event/${id}`) // Запрос на получение данных о событии
      .then((response) => {
        this.setState({ selectedEvent: response.data }); // Устанавливаем выбранное событие
      })
      .catch((error) => console.error("Ошибка при загрузке события:", error));
  };

  handleEdit = (id) => {
    this.props.navigate(`/edit-event/${id}`);
  };

  handleDelete = (id) => {
    if (window.confirm("Вы уверены, что хотите удалить это событие?")) {
      axiosInstance
        .delete(`/event/${id}`)
        .then(() => {
          this.setState((prevState) => ({
            events: prevState.events.filter((event) => event._id !== id),
            selectedEvent: null, // Убираем выбранное событие, если оно удалено
          }));
          alert("Событие успешно удалено.");
        })
        .catch((error) => {
          console.error("Ошибка при удалении события:", error);
          alert("Не удалось удалить событие.");
        });
    }
  };

  render() {
    const { events, selectedEvent } = this.state;

    return (
      <div className="creating-page">
        <header className="main-header"></header>
        <div className="profile-page">
          <LeftSlidebar />
          <div className="content">
            <h1>Список событий</h1>
            <table className="event-table">
              <thead>
                <tr>
                  <th>№</th>
                  <th>Название</th>
                  <th>Время проведения</th>
                  <th>Действия</th>
                </tr>
              </thead>
              <tbody>
                {events.map((event, index) => (
                  <tr key={event._id}>
                    <td>{index + 1}</td>
                    <td>{event.eventName}</td>
                    <td>{new Date(event.eventDate).toLocaleDateString()}</td>
                    <td>
                      <button className="check" onClick={() => this.handleView(event._id)}>
                        Просмотр
                      </button>
                      <button className="change" onClick={() => this.handleEdit(event._id)}>
                        Изменить
                      </button>
                      <button onClick={() => this.handleDelete(event._id)}>
                        Удалить
                      </button>
                    </td>
                  </tr>
                ))}
              </tbody>
            </table>

            {selectedEvent && (
              <div className="event-details">
                <h2>Детали события</h2>
                <table>
                  <tbody>
                    <tr>
                      <th>Название мероприятия</th>
                      <td>{selectedEvent.eventName}</td>
                    </tr>
                    <tr>
                      <th>Тип мероприятия</th>
                      <td>{selectedEvent.eventType}</td>
                    </tr>
                    <tr>
                      <th>Дата проведения</th>
                      <td>{new Date(selectedEvent.eventDate).toLocaleString()}</td>
                    </tr>
                    <tr>
                      <th>Проверяющие</th>
                      <td>
                        <ul>
                          {selectedEvent.emailFields.map((email, index) => (
                            <li key={index}>{email}</li>
                          ))}
                        </ul>
                      </td>
                    </tr>
                    <tr>
                      <th>Участники</th>
                      <td>
                        <ul>
                          {selectedEvent.participants.map((participant, index) => (
                            <li key={index}>
                              {participant.name} (ИИН: {participant.iin})
                            </li>
                          ))}
                        </ul>
                      </td>
                    </tr>
                  </tbody>
                </table>
              </div>
            )}
          </div>
        </div>
      </div>
    );
  }
}

export default withNavigation(EventsList);
